function recommanderSoin(answers) {
  const { skin_type, main_concern, tone } = answers;
  const isMelanisee = ["tan", "deep"].includes(tone);

  // HYPERPIGMENTATION — priorité absolue
  if (main_concern === "pigmentation") {
    // Taches tenaces sur peau foncée → Peeling Mélanine
    if (isMelanisee) return SOINS.find(s => s.id === "peeling_melanine");
    // Sinon Cure Gold Skin (3 soins progressifs)
    return SOINS.find(s => s.id === "cure_gold");
  }

  // ACNÉ / IMPERFECTIONS
  if (main_concern === "acne") {
    if (skin_type === "oily" || skin_type === "combo") return SOINS.find(s => s.id === "purifiant");
    return SOINS.find(s => s.id === "glow");
  }

  // DÉSHYDRATATION / MANQUE D'ÉCLAT
  if (main_concern === "hydration") {
    // Peau sèche, terne, déshydratée, grasse → HydraFace
    return SOINS.find(s => s.id === "hydraface");
  }

  // RIDES / ANTI-ÂGE / TEXTURE / DUVET
  if (main_concern === "aging") {
    // Dermaplaning pour texture + duvet + éclat
    return SOINS.find(s => s.id === "dermaplaning");
  }

  // SENSIBILITÉ / RÉACTIVITÉ
  if (main_concern === "sensitivity") {
    return SOINS.find(s => s.id === "glow");
  }

  // SELON TYPE DE PEAU (fallback)
  if (skin_type === "oily" || skin_type === "combo") return SOINS.find(s => s.id === "purifiant");
  if (skin_type === "dry") return SOINS.find(s => s.id === "hydraface");
  if (skin_type === "sensitive") return SOINS.find(s => s.id === "glow");

  // Défaut : Diagnostic Premium
  return SOINS.find(s => s.id === "diagnostic_premium");
}

